('981', 'ว่าที่ร้อยตรีหญิง');
INSERT INTO `quickwin_options` (`OptionID`, `OptionText`, `display_order`) VALUES
(1, 'ปลูกฝังความรักในสถาบันหลักของชาติ และน้อมนำพระบรมราโชบายด้านการศึกษาสู่การปฏิบัติ', 1),
(2, 'ส่งเสริมและพัฒนาการจัดการเรียนรู้ ภูมิศาสตร์ ประวัติศาสตร์ หน้าที่พลเมือง ศีลธรรม และประชาธิปไตย', 2),
(3, 'ปรับกระบวนการจัดการเรียนรู้ให้หลากหลาย ด้วยเทคโนโลยีที่ทันสมัย', 3),
(4, 'ส่งเสริมการอ่านให้เป็นวิถีปฏิบัติ เพื่อให้ผู้เรียนค้นหาและพัฒนาต่อยอดองค์ความรู้ อย่างต่อเนื่อง', 4),
(5, 'ส่งเสริม สนับสนุนกิจกรรมพัฒนาผู้เรียน', 5),
(6, 'พัฒนาการจัดการศึกษาสำหรับเด็กที่มีความต้องการจำเป็นพิเศษ', 6),
(7, 'ส่งเสริมศักยภาพผู้เรียนรายบุคคลสู่ความเป็นเลิศ', 7),
(8, 'เสริมสร้างความปลอดภัยของผู้เรียน ครูและบุคลากรทางการศึกษา และสถานศึกษา', 8),
(9, 'เพิ่มโอกาสและสร้างความเสมอภาคทางการศึกษา', 9),
(10, 'พัฒนาครูและบุคลากรทางการศึกษาให้มีความรู้ ความสามารถ และทักษะที่ทันสมัย', 10),
(11, 'จัดการเรียนรู้และวัดประเมินผลที่มุ่งเน้นพัฒนาการตามศักยภาพผู้เรียนรายบุคคล', 11),
(12, 'พัฒนาระบบบริหารจัดการให้มีประสิทธิภาพ ถูกต้อง รวดเร็ว ประโยชน์ ประหยัด โปร่งใสและตรวจสอบได้', 12),
(13, 'ระบบนิเทศภายในสถานศึกษา', 13),
(14, 'ลดภาระครู', 14),
(15, 'เพิ่มสวัสดิการครูและบุคลากรทางการศึกษา', 15),
(16, 'ส่งเสริมการเรียนดี มีคุณธรรม', 16),
(17, 'ส่งเสริม สนับสนุน พัฒนาหลักสูตรสถานศึกษา', 17),
(18, 'ส่งเสริมและพัฒนากระบวนการเรียนรู้', 18),
(19, 'ส่งเสริมและพัฒนาการประกันคุณภาพการศึกษา', 19),
(20, 'ส่งเสริมและพัฒนาการวัดและประเมินผลการศึกษา', 20),
(21, 'การติดตาม ตรวจสอบ ประเมินผล และนิเทศการศึกษาของเขตพื้นที่การศึกษา (ก.ต.ป.น.)', 21),
(22, 'การส่งเสริมและพัฒนาศักยภาพผู้เรียนตามแนวทางพหุปัญญา', 22);
