('3501200441290', '1101500222329', 'ศ21101', 'ศิลปะ', 1, '2025-12-17', '- ช่วงท้ายชั่วโมง ยังไม่มีการสรุปว่าวันนี้ได้มีการเรียนรู้อะไรไปบ้าง\r\n- การนำเสนอหน้าชั้นยังไม่ค่อยน่่าสนใจ อาจ ปรับเปลี่ยนวิธีการ นำเสนอของนักเรียน แล้วมีการอภิปราย หรือการมีส่วนร่วมของเพื่อนร่วมชั้นมากขึ้น เช่น ใช้ แอปปริเชั่น เกม เป็นต้น', '2025-12-17 08:24:23', '2568', '2', NULL, '', 1, '2025-12-17 17:42:42'),
('1520590004267', '1103700582495', 'พ21104', 'พลศึกษา', 1, '2026-01-07', '', '2026-01-13 09:47:53', '2568', '2', NULL, 'รอบหน้า ขอให้ผู้นิเทศคนเดิมมานะคะ', 1, '2026-01-14 12:50:35'),
('3501200441290', '1103701262613', 'ส33102', 'สังคมศึกษาฯ', 1, '2025-12-09', 'ในช่วงท้ายของชั่วโมง ยังไม่เห็นว่าครู ได้มีการสรุปผลการเรียนรู้ของวันนี้ ว่าได้เรียนรู้อะไรบ้าง เพื่อเชื่อมโชงไปสู่การให้นักเรียนไปฝึกฝนต่อที่บ้าน', '2025-12-17 06:30:19', '2568', '2', NULL, '', 1, '2025-12-17 20:50:32'),
