('5520700016810', '3510600050157', 'ว33222', 'เคมี', 1, '2025-12-23', '', '2026-01-15 08:21:25', '2568', '2', NULL, NULL, 0, NULL),
('1529900270499', '3520101197870', 'ก.....', 'ภาษาเกาหลี', 1, '2026-03-20', 'ครูผู้สอนมีความมุ่งมั่น ทุ่มเทในการจัดการเรียนรู้ที่เน้นผู้เรียนเป็นศูนย์กลางได้อย่างน่าชื่นชม มีการออกแบบกิจกรรมที่หลากหลาย ใช้สื่อประกอบการสอนอย่างเหมาะสม และสร้างบรรยากาศชั้นเรียนที่อบอุ่น ปลอดภัย และเอื้อต่อการเรียนรู้ของผู้เรียนได้เป็นอย่างดี ขอ', '2026-03-20 08:50:46', '2568', '1', NULL, NULL, 0, NULL),
('3210400040835', '3520300217323', 'ง33202', 'การถนอมอาหาร', 1, '2026-01-07', 'นักเรียนสรุปองค์ความรู้โดยใช้สื่อเทคโนโลยีที่สอดคล้องกับชีวิตประจำวัน เพื่อเป็นการเพิ่มทักษะการใช้สื่อดิจิทัล', '2026-01-08 09:22:15', '2568', '2', NULL, NULL, 0, NULL),
('1529900270499', '3520500045658', 'ศ32102', 'ดนตรีศึกษา', 1, '2025-12-10', 'ครูศรีรัตน์ มีการจัดการเรียนรู้ได้อย่างโดดเด่นและมีคุณภาพ โดยเฉพาะการเลือกใช้สื่อการสอนที่มีความหลากหลายและสร้างสรรค์ ทั้งสื่อ\r\nภาพยนตร์ประวัติศาสตร์ สื่อจริงจากเครื่องดนตรีระนาดเอก และการบูรณาการเทคโนโลยีสมัยใหม่ เช่น การใช้ AI Gemini ในการวัดและประเมิน\r\nผล ซึ่งช่วยส่งเสริมให้ผู้เรียนเกิดความเข้าใจอย่างเป็นระบบ เห็นภาพชัดเจน และมีความสนใจในเนื้อหามากขึ้น\r\nครูมีการสื่อสารที่ชัดเจน อธิบายอย่างเข้าใจง่าย สร้างบรรยากาศการเรียนรู้ที่เป็นกันเอง กระตุ้นให้ผู้เรียนกล้าแสดงออก กล้าตอบคำถาม และมี\r\nส่วนร่วมในชั้นเรียนอย่างต่อเนื่อง นอกจากนี้ครูยังเป็นแบบอย่างที่ดีในการใช้คำศัพท์ดนตรีไทยและถ่ายทอดคุณค่าทางวัฒนธรรมได้อย่างลึกซึ้ง\r\nและเหมาะสมกับระดับชั้น', '2025-12-15 08:13:08', '2568', '2', NULL, '', 1, '2026-01-05 17:43:42'),
('1529900192498', '3520500047022', 'ค33104', 'คณิตศาสตร์', 1, '2025-12-12', '', '2025-12-15 08:49:17', '2568', '2', NULL, '', 1, '2025-12-15 15:51:20'),
('3210400040835', '3520600019616', 'ว23286', 'วิทยาการเทคโนโลยี 6', 1, '2025-12-16', '', '2025-12-17 08:31:00', '2568', '2', NULL, '', 1, '2025-12-17 17:41:39'),
('1529900270499', '3520700211675', 'ภาษาอังกฤษ4', 'อ22102', 1, '2026-03-20', 'ขอชื่นชมครูผู้สอนที่ออกแบบการจัดการเรียนรู้ได้อย่างมีคุณภาพสูง ครูมีความสามารถในการสร้างบรรยากาศชั้นเรียนที่อบอุ่น กระตือรือร้น และเอื้อต่อการเรียนรู้ โดยใช้สื่อและกิจกรรมที่หลากหลาย ทั้งเกมแข่งขัน ระบบรางวัล Sticker และสื่อ Canva ที่ออกแบบอย่างสวยงามและสอดคล้องกับเนื้อหา กระบวนการจัดการเรียนรู้ตามรูปแบบ 3P (Presentation–Practice–Production) มีความต่อเนื่องและเป็นระบบ ผู้เรียนได้ฝึกทักษะครบทั้งการฟัง พูด อ่าน และเขียน รวมทั้งได้ประเมินซึ่งกันและกันผ่านแบบประเมินเพื่อนประเมินเพื่อน นับเป็นตัวอย่างที่ดีของการจัดการเรียนรู้เชิงรุก (Active Learning) ที่เน้นผู้เรียนเป็นสำคัญ และสมควรได้รับการเผยแพร่เป็นแนวปฏิบัติที่ดีในระดับโรงเรียนต่อไป', '2026-03-20 08:12:49', '2568', '2', NULL, NULL, 0, NULL),
('1520590004267', '3520800303245', 'พ23103', 'พลศึกษา', 1, '2026-02-12', '', '2026-02-16 06:52:30', '2568', '2', NULL, NULL, 0, NULL),
('1529900270499', '3521000549933', 'ส21102', 'สังคมศึกษา2', 1, '2026-01-14', 'การจัดการเรียนรู้ของครูอุเทน เครือแปง อยู่ในระดับคุณภาพดีมากทุกตัวชี้วัด สะท้อนให้เห็นถึงความเชี่ยวชาญในการออกแบบและจัดกิจกรรมการเรียนรู้เชิงรุกที่เน้นผู้เรียนเป็นสำคัญอย่างแท้จริง การใช้กระบวนการคิดขั้นสูงเชิงระบบ GPAS 5 Steps เป็นกรอบในการจัดการเรียนรู้ทำให้นักเรียนได้พัฒนาทักษะการคิดอย่างเป็นระบบ ตั้งแต่การสังเกต วิเคราะห์ ปฏิบัติ สื่อสาร และประเมินตนเอง\r\nกิจกรรมที่หลากหลายและเชื่อมโยงกับชีวิตจริง เช่น การจำแนกประเภททรัพย์สินทางปัญญา การเล่นเกม และการออกแบบผลิตภัณฑ์ ช่วยกระตุ้นให้นักเรียนเห็นความสำคัญและนำความรู้ไปใช้ในชีวิตประจำวันได้อย่างแท้จริง การให้นักเรียนมีส่วนร่วมในการประเมินตนเองและสะท้อนการเรียนรู้ยังช่วยส่งเสริมทักษะการกำกับการเรียนรู้ของตนเอง ซึ่งเป็นทักษะสำคัญในศตวรรษที่ 21', '2026-01-15 02:40:39', '2568', '2', NULL, '', 1, '2026-01-19 20:38:04'),
('3210400040835', '3521200027370', 'ท23102', 'ภาษาไทย', 1, '2026-01-27', '', '2026-02-09 03:51:45', '2568', '2', NULL, NULL, 0, NULL),
('1529900270499', '3521200324790', 'ง23102', 'เกษตร', 1, '2026-01-28', '', '2026-01-29 08:48:15', '2568', '2', NULL, '', 1, '2026-01-29 20:25:48'),
('3210400040835', '3521300176954', 'ท33102', 'ภาษาไทย', 1, '2026-01-07', 'การบริหารเวลาในการทำกิจกรรม ควรกำหนดให้แน่ชัด ฝึกให้นักเรียนทำตามกำหนดเวลา\r\nปรับกิจกรรมเป็นการใช้ Active Learning ให้มากขึ้น เพื่อเปลี่ยนจากกิจกรรมการบรรยายโดยครูและให้นักเรียนได้เป็นผู้สังเคราะห์ความรู้ด้วยตนเอง', '2026-01-08 09:15:45', '2568', '2', NULL, '-', 1, '2026-01-26 11:22:50'),
('1529900192498', '3521300217600', 'ท21102', 'ภาษาไทย', 1, '2026-01-26', 'คุณครูสามารถเชื่อมโยงกิจกรรมการเรียนรู้ให้สอดคล้องกับชีวิตประจำวันหรือบริบทสังคมโดยการตั้งคำถาม เช่น 1. ชีวิตจริงนักเรียนเคยเห็นหรือรู้สึกถึงความรักของพ่อแม่ในรูปแบบใดบ้าง \r\n2. ถ้าวันหนึ่งนักเรียนหลงกับครอบครัวนักเรียนคิดว่าพ่อแม่จะรู้สึกอย่างไร จะพยายามตามหาเราหรือไม่ เพราะเหตุใด 3. ในสังคมปัจจุบันมีคนที่ขาดความอบอุ่นเหมือนหญิงชราในบทเพลงหรือไม่ แล้วเราควรปฏิบัติต่อเขาอย่างไร เป็นต้น', '2026-02-09 03:14:07', '2568', '2', NULL, '', 1, '2026-02-09 10:47:47'),
('1529900270499', '3529900088484', 'อ22102', 'ภาษาอังกฤษพื้นฐาน', 1, '2026-01-27', '1.การเลือกเนื้อหาที่เหมาะสม: หัวข้อเรื่อง smartphones และ video games เป็นเรื่องที่ใกล้ตัวและเกี่ยวข้องกับชีวิตประจำวันของนักเรียนวัยรุ่นอย่างแท้จริง ทำให้นักเรียนมีแรงจูงใจในการเรียนรู้สูง และเห็นคุณค่าของภาษาอังกฤษในการเข้าถึงข้อมูลและความรู้ในโลกยุคดิจิทัล\r\n2.การออกแบบกิจกรรมที่เน้นผู้เรียนเป็นศูนย์กลาง: ครูออกแบบกิจกรรมให้นักเรียนเป็นผู้ลงมือปฏิบัติและสร้างความรู้ด้วยตนเองผ่านการอ่าน การฟัง การวิเคราะห์ และการอภิปราย ซึ่งสอดคล้องกับแนวคิด constructivism และ active learning อย่างแท้จริง\r\n3.การบูรณาการทักษะอย่างลงตัว: แผนการสอนมีการบูรณาการทักษะทั้ง 4 ด้าน (ฟัง พูด อ่าน เขียน) พร้อมกับทักษะการคิดขั้นสูง (critical thinking และ analytical skills) ได้อย่างกลมกลืนและเป็นธรรมชาติ สะท้อนการใช้ภาษาในชีวิตจริง\r\n4.การใช้สื่อที่หลากหลาย: มีการใช้บทความ ภาพประกอบ บทสนทนาเสียง และ graphic organizers ที่หลากหลาย ช่วยรองรับนักเรียนที่มีรูปแบบการเรียนรู้แตกต่างกัน และทำให้บทเรียนน่าสนใจ\r\n5.บรรยากาศการเรียนรู้ที่เอื้อต่อการพัฒนา: ครูสร้างสภาพแวดล้อมที่ปลอดภัยทางจิตใจให้นักเรียนกล้าแสดงออก กล้าลองผิดลองถูก และได้เรียนรู้จากเพื่อนผ่านการทำงานเป็นคู่และกลุ่ม', '2026-01-27 03:45:39', '2568', '2', NULL, 'ศน.ให้คำแนะนำในการจัดทำแผนการจัดการเรียนรู้ที่ชัดเจนให้แนวคิดที่เป็นประโยชน์และให้กำลังใจครูในการเลื่อนวิทยฐานะเป็นอย่างดี', 1, '2026-01-27 14:58:22'),
('1529900191467', '3529900174411', 'ศ23102', 'ศิลปะ', 1, '2026-01-14', '', '2026-01-14 04:27:55', '2568', '2', NULL, '-', 1, '2026-01-14 19:15:01'),
