('3210400040835', '3529900345193', 'ส21104', 'สังคมศึกษา สาระภูมิศาสตร์', 1, '2026-01-27', 'เปิดโอกาสให้ผู้เรียนได้มีโอกาสสรุปความรู้ด้วยตนเอง', '2026-02-09 03:55:15', '2568', '2', NULL, NULL, 0, NULL),
('1520590004267', '3529900399391', 'พ21104', 'พลศึกษา', 1, '2025-12-09', '', '2026-01-13 09:25:17', '2568', '2', NULL, NULL, 0, NULL),
('1529900270499', '3571100377387', 'ง21102', 'คหกรรม', 1, '2025-12-19', 'คาบกิจกรรมของครูทัดทรวงมีความน่าสนใจ /แผนการจัดการเรียนรู้ฉบับนี้มีความโดดเด่นในการจัดกิจกรรมที่เปิดโอกาสให้นักเรียนได้ลงมือปฏิบัติจริงอย่างเป็นรูปธรรม ผ่านกระบวนการเรียนรู้เชิงรุก นักเรียนสามารถสร้างองค์ความรู้ด้วยตนเองจากประสบการณ์ตรง ไม่ใช่เพียงการรับความรู้จากครูผู้สอน ส่งผลให้นักเรียนเกิดความเข้าใจอย่างลึกซึ้งและยั่งยืนนอกจากนี้ นักเรียนได้เรียนรู้การทำงานเป็นทีม มีการวางแผน แบ่งหน้าที่ และร่วมกันแก้ปัญหาระหว่างการปฏิบัติกิจกรรมอย่างเหมาะสม ซึ่งช่วยพัฒนาทักษะการทำงานร่วมกับผู้อื่น ความรับผิดชอบ และทักษะทางสังคมได้เป็นอย่างดีกิจกรรมการเรียนรู้ยังส่งเสริมให้นักเรียนได้ใช้ความคิดสร้างสรรค์ในการสร้างสรรค์ผลงาน จากการบูรณาการภูมิปัญญาท้องถิ่นเรื่องข้าวหนุกงา ซึ่งเป็นอาหารอัตลักษณ์ที่สอดคล้องกับฤดูกาลและบริบทชุมชน นักเรียนเกิดความภาคภูมิใจในผลงานของตนเอง และสามารถนำความรู้และทักษะที่ได้รับไปประยุกต์ใช้ในชีวิตจริงได้อย่างเหมาะสม', '2025-12-19 07:18:25', '2568', '2', NULL, '', 1, '2025-12-28 17:44:25'),
('1520590004267', '3610400208473', 'ว33102', 'วิทยาศาสตร์และเทคโนโลยี2', 1, '2025-12-23', '', '2026-01-13 09:52:22', '2568', '2', NULL, '', 1, '2026-01-26 15:42:01'),
('1529900270499', '3630100256642', 'ส 33104', 'ประวัติศาสตร์', 1, '2026-03-12', 'กิจกรรมการจัดการเรียนรู้สอนให้นักเรียนทำตุงไส้หมูเป็นนวัตกรรมการสอนที่หาได้ยากยิ่ง เพราะไม่ใช่เพียงการสอนเนื้อหาวัฒนธรรม แต่เป็นการให้นักเรียนได้ \"เป็นส่วนหนึ่งของวัฒนธรรม\" ผ่านการลงมือทำด้วยตนเอง จุดเด่นสูงสุดของแผนนี้คือการออกแบบกิจกรรม Service Learning ที่สมบูรณ์แบบ — นักเรียนไม่เพียงทำตุงในห้องเรียน แต่ยังนำความรู้กลับไปสอนคนที่บ้าน ถ่ายทำคลิปวีดีโอ และนำตุงไปถวายวัดในชุมชนจริง ซึ่งเป็นวงจรการเรียนรู้ที่เชื่อมโยงโรงเรียน-บ้าน-วัด-ชุมชนในแบบที่ลึกซึ้งและมีความหมายเชิงจิตวิญญาณอย่างยิ่ง การให้นักเรียนวิเคราะห์เปรียบเทียบวัสดุดั้งเดิมกับสมัยใหม่ยังสะท้อนถึงครูที่เข้าใจว่าการอนุรักษ์ต้องเดินคู่กับการปรับตัวให้ทันยุคสมัย ภาพหลักฐานการสอนที่นักเรียนนั่งสร้างสรรค์ผลงานกันอย่างมีความสุขเป็นประจักษ์พยานของห้องเรียนที่มีชีวิตชีวาและงดงาม', '2026-03-12 02:50:58', '2568', '2', NULL, '', 1, '2026-03-12 11:48:53'),
('1529900192498', '5521090000096', 'ท21102', 'ภาษาไทย', 1, '2026-01-14', '', '2026-01-15 09:21:57', '2568', '2', NULL, '', 1, '2026-01-15 16:44:31');
